/**
 * Calculate invoice totals.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }}
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => {
    const discountPercent = line.discountPercent ?? 0;
    const lineTotal_ = lineTotal(line);
    const lineDiscount = roundCents(lineTotal_ * discountPercent / 100);
    let totalLineDiscount = lineDiscount;

    if (line.qty >= 10) {
      const discountedAmount = lineTotal_ - lineDiscount;
      const bulkDiscount = roundCents(discountedAmount * 2.5 / 100);
      totalLineDiscount += bulkDiscount;
    }

    return sum + totalLineDiscount;
  }, 0);
  const vat = invoice.lines.reduce((sum, line) => {
    const discountPercent = line.discountPercent ?? 0;
    const lineTotal_ = lineTotal(line);
    const lineDiscount = roundCents(lineTotal_ * discountPercent / 100);
    let discountedAmount = lineTotal_ - lineDiscount;

    if (line.qty >= 10) {
      const bulkDiscount = roundCents(discountedAmount * 2.5 / 100);
      discountedAmount -= bulkDiscount;
    }

    const lineVat = roundCents(discountedAmount * line.vatRate / 100);
    return sum + lineVat;
  }, 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

