test('invoiceTotals: multiple lines with different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 5000, discountPercent: 0, vatRate: 21 },
      { qty: 100, unitPrice: 5000, discountPercent: 0, vatRate: 9 },
      { qty: 100, unitPrice: 5000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.strictEqual(totals.subtotal, 1500000);
  assert.strictEqual(totals.vat, 105000 + 45000 + 0);
  assert.strictEqual(totals.total, 1500000 + 150000);
});

test('invoiceTotals: VAT per line is rounded independently', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 100, discountPercent: 0, vatRate: 21 },
      { qty: 3, unitPrice: 100, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.strictEqual(totals.subtotal, 600);
  const lineVat1 = Math.round(300 * 21 / 100);
  const lineVat2 = Math.round(300 * 21 / 100);
  const expectedVat = lineVat1 + lineVat2;
  assert.strictEqual(totals.vat, expectedVat);
});

test('invoiceTotals: VAT with discount and different rates', () => {
  const invoice = {
    lines: [
      { qty: 50, unitPrice: 10000, discountPercent: 20, vatRate: 21 },
      { qty: 50, unitPrice: 10000, discountPercent: 10, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const sub1 = 50 * 10000;
  const sub2 = 50 * 10000;
  const subtotal = sub1 + sub2;
  const disc1 = Math.round(sub1 * 20 / 100);
  const disc2 = Math.round(sub2 * 10 / 100);
  const discount = disc1 + disc2;
  const discAmt1 = sub1 - disc1;
  const discAmt2 = sub2 - disc2;
  const vat1 = Math.round(discAmt1 * 21 / 100);
  const vat2 = Math.round(discAmt2 * 9 / 100);
  const vat = vat1 + vat2;
  assert.strictEqual(totals.subtotal, subtotal);
  assert.strictEqual(totals.discount, discount);
  assert.strictEqual(totals.vat, vat);
  assert.strictEqual(totals.total, subtotal - discount + vat);
});

test('invoiceTotals: returns object with vat key', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 10000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok(totals.hasOwnProperty('vat'));
  assert.ok(totals.hasOwnProperty('subtotal'));
  assert.ok(totals.hasOwnProperty('discount'));
  assert.ok(totals.hasOwnProperty('total'));
});

