test('invoiceTotals: VAT with discount and different rates', () => {
  const invoice = {
    lines: [
      { qty: 50, unitPrice: 10000, discountPercent: 20, vatRate: 21 },
      { qty: 50, unitPrice: 10000, discountPercent: 10, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const sub1 = 50 * 10000; // 500000
  const sub2 = 50 * 10000; // 500000
  const subtotal = sub1 + sub2; // 1000000
  // Line 1: 20% discount + 2.5% bulk
  const disc1_1 = Math.round(sub1 * 20 / 100); // 100000
  const bulk1 = Math.round((sub1 - disc1_1) * 2.5 / 100); // 10000
  const disc1 = disc1_1 + bulk1; // 110000
  // Line 2: 10% discount + 2.5% bulk
  const disc2_1 = Math.round(sub2 * 10 / 100); // 50000
  const bulk2 = Math.round((sub2 - disc2_1) * 2.5 / 100); // 11250
  const disc2 = disc2_1 + bulk2; // 61250
  const discount = disc1 + disc2; // 171250
  // VAT after both discounts
  const discAmt1 = sub1 - disc1; // 390000
  const discAmt2 = sub2 - disc2; // 438750
  const vat1 = Math.round(discAmt1 * 21 / 100); // 81900
  const vat2 = Math.round(discAmt2 * 9 / 100); // 39488
  const vat = vat1 + vat2; // 121388
  assert.strictEqual(totals.subtotal, subtotal);
  assert.strictEqual(totals.discount, discount);
  assert.strictEqual(totals.vat, vat);
  assert.strictEqual(totals.total, subtotal - discount + vat);
});

