    ],
  };
  const totals = invoiceTotals(invoice);
  assert.strictEqual(totals.subtotal, 1500000);
  // Each line: 500000 * 2.5% = 12500 bulk discount
  // Total discount: 37500
  // VAT: (500000-12500)*21% + (500000-12500)*9% + (500000-12500)*0%
  //    = 487500*21% + 487500*9% + 0
  //    = 102375 + 43875 = 146250
  assert.strictEqual(totals.discount, 37500);
