test('createInvoice: silver customer tier discount with invoiceTotals', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 100 }],
  });
  assert.strictEqual(result.ok, true);
  const invoice = result.value;
  const totals = invoiceTotals(invoice);
  assert.strictEqual(totals.subtotal, 850000);
  // 2.5% tier + 2.5% bulk = 41969
  assert.strictEqual(totals.discount, 41969);
  const discountedAmount = 850000 - 41969;
