test('invoiceTotals: single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepStrictEqual(totals, { subtotal: 42500, discount: 0, vat: 8925, voucher: 0, total: 51425 });
});

test('invoiceTotals: multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 2, unitPrice: 980, discountPercent: 0, vatRate: 21 },
      { qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expected = 10 * 9500 + 2 * 980 + 100 * 37;
  // Line 1: qty=10, bulk discount applies: 95000 * 2.5% = 2375
  const vat1 = Math.round((95000 - 2375) * 21 / 100); // 19451
  // Line 2: qty=2, no bulk discount
  const vat2 = Math.round(1960 * 21 / 100); // 411
  // Line 3: qty=100, bulk discount applies: 3700 * 2.5% = 92
  const vat3 = Math.round((3700 - 92) * 9 / 100); // 324
  const expectedVat = vat1 + vat2 + vat3;
  assert.strictEqual(totals.subtotal, expected);
  assert.strictEqual(totals.discount, 2467); // 2375 + 92
  assert.strictEqual(totals.vat, expectedVat);
  assert.strictEqual(totals.total, expected - 2467 + expectedVat);
});

