test('invoiceTotals: with invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });
  assert.strictEqual(result.ok, true);
  const invoice = result.value;
  const totals = invoiceTotals(invoice);
  const expected = 5 * 8500 + 2 * 980;
  const vat1 = Math.round(42500 * 21 / 100);
  const vat2 = Math.round(1960 * 21 / 100);
  const expectedVat = vat1 + vat2;
  assert.strictEqual(totals.subtotal, expected);
  assert.strictEqual(totals.discount, 0);
  assert.strictEqual(totals.vat, expectedVat);
  assert.strictEqual(totals.total, expected + expectedVat);
});

