test('invoiceTotals: multiple lines with different discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 0 },
      { qty: 5, unitPrice: 8500, discountPercent: 20, vatRate: 0 },
      { qty: 2, unitPrice: 8500, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const sub1 = 10 * 8500; // 85000
  const sub2 = 5 * 8500; // 42500
  const sub3 = 2 * 8500; // 17000
  const subtotal = sub1 + sub2 + sub3; // 144500
  // Line 1: 10% discount + 2.5% bulk
  const discount1 = Math.round(sub1 * 10 / 100); // 8500
  const bulk1 = Math.round((sub1 - discount1) * 2.5 / 100); // 1912
  // Line 2: 20% discount only (qty < 10)
  const discount2 = Math.round(sub2 * 20 / 100); // 8500
  // Line 3: no discount
  const discount3 = 0;
  const discount = discount1 + bulk1 + discount2 + discount3; // 18912
  assert.strictEqual(totals.subtotal, subtotal);
  assert.strictEqual(totals.discount, 18912);
  assert.strictEqual(totals.vat, 0);
  assert.strictEqual(totals.total, subtotal - discount);
});

